export const isEligibleAge = (query: { age: string }): boolean => {
  const age = parseInt(query.age, 10)
  return age >= 1 && age <= 12
}

export const totalFromRawBody = (raw: string): number => {
  const body = JSON.parse(raw)
  return body.items.reduce((sum: number, item: { price: number }) => sum + item.price, 0)
}

export const adoptFromRequest = (request: { payload: { petId: string } }): Adoption => {
  const petId = request.payload.petId
  return adopt(petId)
}

interface CustomerRow { first_name: string; total: string; loyalty_years: number }
interface CustomerTable { findOne: (id: string) => Promise<CustomerRow | null> }

export const customerTotalWithDiscount = async (customers: CustomerTable, id: string): Promise<number> => {
  const row = await customers.findOne(id)
  if (row === null) return 0
  const total = Number(row.total)
  return row.loyalty_years >= 5 ? total * 0.9 : total
}

export const isExpired = (response: { adoptedAt: string }): boolean => {
  const adoptedAt = Date.parse(response.adoptedAt)
  return Date.now() - adoptedAt > 1000 * 60 * 60 * 24 * 30
}

import Joi from 'joi'

const schema = Joi.object({ age: Joi.number().required() })

export const acceptOrRejectPet = (payload: unknown): string => {
  const { value, error } = schema.validate(payload)
  return error ? 'rejected' : value.age >= 1 ? 'accepted' : 'too-young'
}

interface PetRow { first_name: string; last_name: string }

export const toPet = (row: PetRow): { firstName: string; lastName: string } => {
  return { firstName: row.first_name, lastName: row.last_name }
}

export const handleAdopt = (request: { payload: { petId: string } }, adoptionService: { adopt: (petId: string) => Adoption }): Adoption => {
  const petId = request.payload.petId
  return adoptionService.adopt(petId)
}

export const formatDate = (date: Date): string => {
  const isoDate = date.toISOString().slice(0, 10)
  return isoDate
}

interface Money { cents: number }

export const parseMoney = (raw: string): Money => {
  return { cents: Math.round(Number(raw) * 100) }
}

interface Pet { id: string; name: string }

export const toResponse = (pet: Pet): { id: string; name: string } => {
  return { id: pet.id, name: pet.name }
}

export const splitFullName = (fullName: string): { firstName: string; lastName: string } => {
  const [firstName, lastName] = fullName.split(' ')
  return { firstName, lastName }
}

interface Money { cents: number }

export const total = (amounts: Money[]): Money => {
  return { cents: amounts.reduce((sum, amount) => sum + amount.cents, 0) }
}

enum Status { Available, Adopted }

export const matchesStatus = (order: { status: Status }, filter: { status: Status }): boolean => {
  return order.status === filter.status
}

export const requiresReview = (payment: { amount: string }): boolean => {
  const amount = Number(payment.amount)
  return amount > 10000
}

export const readMaxRetries = (env: Record<string, string | undefined>): number => {
  const maxRetries = Number(env.MAX_RETRIES)
  if (!Number.isInteger(maxRetries) || maxRetries <= 0) {
    throw new Error(`MAX_RETRIES must be a positive integer, received: "${env.MAX_RETRIES}"`)
  }
  return maxRetries
}

export const attachRequestId = (request: { headers: Record<string, string | undefined>; app: { requestId?: string } }, generateId: () => string, log: { debug: (message: string, meta: unknown) => void }): string => {
  const suppliedRequestId = request.headers['x-request-id']
  request.app.requestId = suppliedRequestId ?? generateId()
  if (!suppliedRequestId) {
    log.debug('Generated X-Request-Id; caller sent none', { requestId: request.app.requestId })
  }
  return 'continue'
}

export const updatePet = async (input: { payload: { name: string } }, petService: { update: (payload: { name: string }) => Promise<Pet | null> }, notFound: (message: string) => Error): Promise<Pet> => {
  const updated = await petService.update(input.payload)
  if (updated === null) {
    throw notFound('No pet found')
  }
  return updated
}

interface ExternalTeamRow { id: string; is_routing: boolean }
interface MappingRow { group_name: string; externalTeams: ExternalTeamRow[] }
interface Mapping { groupName: string; externalTeams: Array<{ id: string; isRouting: boolean }> }
interface MappingTable { findOne: (options: { where: { group_name: string }; include: string }) => Promise<MappingRow | null> }

const toMapping = (row: MappingRow): Mapping => ({
  groupName: row.group_name,
  externalTeams: row.externalTeams.map(team => ({ id: team.id, isRouting: team.is_routing }))
})

export class PostgresMappingRepository {
  readonly #table: MappingTable

  constructor (table: MappingTable) {
    this.#table = table
  }

  // A mapping may name several external teams; work is filed against the one marked
  // as routing, which the schema allows only one of.
  async matchGroupToExternalId (groupName: string): Promise<string | null> {
    const row = await this.#table.findOne({ where: { group_name: groupName }, include: "externalTeams" })
    if (row === null) {
      return null
    }
    return toMapping(row).externalTeams.find(team => team.isRouting)?.id ?? null
  }
}

export const parsePetPayload = (raw: string): unknown => {
  return JSON.parse(raw)
}
